starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "role_name" {
  description = "Input variable role_name."
  type        = string
  default     = "app-role"
}

variable "policy_name" {
  description = "Input variable policy_name."
  type        = string
  default     = "app-policy"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_iam_role" "this" {
  name = "app-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "this" {
  name = "app-policy"
}

resource "aws_iam_role_policy_attachment" "this" {
  # TODO - Complete the aws_iam_role_policy_attachment resource.
  # Add the arguments and nested blocks required for aws_iam_role_policy_attachment.
}

starter.outputs.tf:
output "role_arn" {
  value = aws_iam_role.this.arn
}

output "policy_arn" {
  value = aws_iam_policy.this.arn
}
